 for(i in seq_len(nrow(ee))){a<-xy(ee$source[i]);b<-xy(ee$target[i]);if(anyNA(c(a,b)))next;tt<-seq(0,1,length.out=80);oi<-match(ee$ome[i],names(cols));off<-(oi-2.5)*1.05;xx<-(1-tt)^3*a[1]+3*(1-tt)^2*tt*(a[1]+(b[1]-a[1])*.38)+3*(1-tt)*tt^2*(b[1]-(b[1]-a[1])*.38)+tt^3*b[1]; yy<-(1-tt)^3*a[2]+3*(1-tt)^2*tt*(a[2]+off)+3*(1-tt)*tt^2*(b[2]+off)+tt^3*b[2];put(polylineGrob(unit(xx,'mm'),unit(yy,'mm'),gp=gpar(col=adjustcolor(cols[ee$ome[i]],alpha.f=.8),lwd=lw(ee$count[i])*72/25.4,lineend='round')))}
