 for(j in 1:7){txt(labels[j],31,ys[j],7,'right');if(j!=4){up<-j<4;sc<-if(j%in%c(1,5))'#CB92BB'else if(j%in%c(3,7))'#8887C4'else'#BCC2C8';yy<-ys[j]+c(if(up)1.3 else -1.3,if(up)-1.0 else 1,if(up)-1 else 1);put(polygonGrob(unit(c(3,1.8,4.2),'mm'),unit(yy,'mm'),gp=gpar(fill=sc,col='#30343B',lwd=.55)))}}
