 txt('No. of analytes',112,top-22,7);nb<-if(k==2)c(100,200,300)else c(200,400,600);for(i in seq_along(nb)){y<-top-27-(i-1)*6;put(circleGrob(unit(115,'mm'),unit(y,'mm'),unit(rad(nb[i]),'mm'),gp=gpar(fill='#818B92',col=NA)));txt(as.character(nb[i]),120,y)}
